-- TMDB-MOVIE-PREPROCESS-066: dry run of process 75 step 1 (movies), the SELECT its
-- INSERT ... SELECT reads, generated from f_buildworkfinancetable(). READ ONLY.
-- Checks the SQL and shows the rows of three witnesses before the first real run.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

SELECT COUNT(*) AS MOVIE_STATEMENTS, SUM(FINANCE_KIND = 'budget') AS BUDGET, SUM(ID_PLACE_WIKIDATA IS NOT NULL) AS WITH_PLACE, SUM(DAT_POINT IS NOT NULL) AS WITH_DATE FROM (
SELECT s.ID_STATEMENT, 'movie' AS ITEM_TYPE, w.ID_MOVIE AS ID_ITEM, s.ID_WIKIDATA,
       IF(s.ID_PROPERTY = 'P2130', 'budget', 'box_office') AS FINANCE_KIND,
       q.AMOUNT, q.UNIT_ID_WIKIDATA AS ID_CURRENCY, CASE q.UNIT_ID_WIKIDATA WHEN 'Q4917' THEN 'USD' WHEN 'Q4916' THEN 'EUR' WHEN 'Q25224' THEN 'GBP' WHEN 'Q8146' THEN 'JPY' WHEN 'Q41044' THEN 'RUB' WHEN 'Q1104069' THEN 'CAD' WHEN 'Q259502' THEN 'AUD' WHEN 'Q39099' THEN 'CNY' END AS CURRENCY_CODE,
       COALESCE((SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P3005' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P17' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1001' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P276' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P291' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1)) AS ID_PLACE_WIKIDATA,
       (SELECT COALESCE(qv.DATE_START, IF(qv.YEAR_VALUE BETWEEN 1000 AND 9999, MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (COALESCE(NULLIF(qv.MONTH_VALUE, 0), 1) - 1) MONTH + INTERVAL (COALESCE(NULLIF(qv.DAY_VALUE, 0), 1) - 1) DAY, NULL)) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_POINT, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS POINT_PRECISION,
       (SELECT COALESCE(qv.DATE_START, IF(qv.YEAR_VALUE BETWEEN 1000 AND 9999, MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (COALESCE(NULLIF(qv.MONTH_VALUE, 0), 1) - 1) MONTH + INTERVAL (COALESCE(NULLIF(qv.DAY_VALUE, 0), 1) - 1) DAY, NULL)) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P580' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_START, (SELECT COALESCE(qv.DATE_START, IF(qv.YEAR_VALUE BETWEEN 1000 AND 9999, MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (COALESCE(NULLIF(qv.MONTH_VALUE, 0), 1) - 1) MONTH + INTERVAL (COALESCE(NULLIF(qv.DAY_VALUE, 0), 1) - 1) DAY, NULL)) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P582' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_END,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1264' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_PERIOD_WIKIDATA, (SELECT qv.AMOUNT FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_QUANTITY_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1352' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS CHART_RANK,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P459' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_METHOD_WIKIDATA,
       s.`RANK` AS WIKIDATA_RANK, s.DISPLAY_ORDER
FROM T_WC_WIKIDATA_STATEMENT s
JOIN T_WC_WIKIDATA_QUANTITY_VALUE q ON q.ID_STATEMENT = s.ID_STATEMENT
JOIN `T_WC_T2S_MOVIE` w ON w.ID_WIKIDATA = s.ID_WIKIDATA AND COALESCE(w.DELETED, 0) = 0
WHERE s.ID_PROPERTY IN ('P2130', 'P2142')
  AND (s.`RANK` IS NULL OR s.`RANK` <> 'deprecated')
  AND q.AMOUNT IS NOT NULL
) x;

SELECT * FROM (
SELECT s.ID_STATEMENT, 'movie' AS ITEM_TYPE, w.ID_MOVIE AS ID_ITEM, s.ID_WIKIDATA,
       IF(s.ID_PROPERTY = 'P2130', 'budget', 'box_office') AS FINANCE_KIND,
       q.AMOUNT, q.UNIT_ID_WIKIDATA AS ID_CURRENCY, CASE q.UNIT_ID_WIKIDATA WHEN 'Q4917' THEN 'USD' WHEN 'Q4916' THEN 'EUR' WHEN 'Q25224' THEN 'GBP' WHEN 'Q8146' THEN 'JPY' WHEN 'Q41044' THEN 'RUB' WHEN 'Q1104069' THEN 'CAD' WHEN 'Q259502' THEN 'AUD' WHEN 'Q39099' THEN 'CNY' END AS CURRENCY_CODE,
       COALESCE((SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P3005' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P17' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1001' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P276' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1), (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P291' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1)) AS ID_PLACE_WIKIDATA,
       (SELECT COALESCE(qv.DATE_START, IF(qv.YEAR_VALUE BETWEEN 1000 AND 9999, MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (COALESCE(NULLIF(qv.MONTH_VALUE, 0), 1) - 1) MONTH + INTERVAL (COALESCE(NULLIF(qv.DAY_VALUE, 0), 1) - 1) DAY, NULL)) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_POINT, (SELECT qv.TIME_PRECISION FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P585' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS POINT_PRECISION,
       (SELECT COALESCE(qv.DATE_START, IF(qv.YEAR_VALUE BETWEEN 1000 AND 9999, MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (COALESCE(NULLIF(qv.MONTH_VALUE, 0), 1) - 1) MONTH + INTERVAL (COALESCE(NULLIF(qv.DAY_VALUE, 0), 1) - 1) DAY, NULL)) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P580' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_START, (SELECT COALESCE(qv.DATE_START, IF(qv.YEAR_VALUE BETWEEN 1000 AND 9999, MAKEDATE(qv.YEAR_VALUE, 1) + INTERVAL (COALESCE(NULLIF(qv.MONTH_VALUE, 0), 1) - 1) MONTH + INTERVAL (COALESCE(NULLIF(qv.DAY_VALUE, 0), 1) - 1) DAY, NULL)) FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_TIME_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P582' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS DAT_END,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1264' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_PERIOD_WIKIDATA, (SELECT qv.AMOUNT FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_QUANTITY_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P1352' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS CHART_RANK,
       (SELECT qv.ID_ITEM FROM T_WC_WIKIDATA_STATEMENT_QUALIFIER sq JOIN T_WC_WIKIDATA_QUALIFIER_ITEM_VALUE qv ON qv.ID_STATEMENT_QUALIFIER = sq.ID_STATEMENT_QUALIFIER WHERE sq.ID_STATEMENT = s.ID_STATEMENT AND sq.ID_QUALIFIER_PROPERTY = 'P459' ORDER BY sq.DISPLAY_ORDER, sq.ID_STATEMENT_QUALIFIER LIMIT 1) AS ID_METHOD_WIKIDATA,
       s.`RANK` AS WIKIDATA_RANK, s.DISPLAY_ORDER
FROM T_WC_WIKIDATA_STATEMENT s
JOIN T_WC_WIKIDATA_QUANTITY_VALUE q ON q.ID_STATEMENT = s.ID_STATEMENT
JOIN `T_WC_T2S_MOVIE` w ON w.ID_WIKIDATA = s.ID_WIKIDATA AND COALESCE(w.DELETED, 0) = 0
WHERE s.ID_PROPERTY IN ('P2130', 'P2142')
  AND (s.`RANK` IS NULL OR s.`RANK` <> 'deprecated')
  AND q.AMOUNT IS NOT NULL
) x
WHERE x.ID_WIKIDATA IN ('Q24871', 'Q25188', 'Q44578')
ORDER BY ID_WIKIDATA, FINANCE_KIND, AMOUNT DESC;
